	@Test
	void blockedTimerCallbackDoesNotDelayAnotherDeadline() throws Exception {
		GatedSource blocked = new GatedSource(true);
		GatedSource other = new GatedSource(true);
		other.release.countDown();
		Timed first = new Timed(blocked, 1);
		Timed second = null;
		Throwable primary = null;
		try {
			assertTrue(blocked.entered.await(10, TimeUnit.SECONDS), "first cancellation callback must start");
			second = new Timed(other, 1);
			assertTrue(other.entered.await(3, TimeUnit.SECONDS),
					"a blocked callback must not delay another result's timer");
			assertEquals(1, blocked.release.getCount(), "the first callback remains blocked at the check");
		} catch (Exception | Error failure) {
			primary = failure;
			throw failure;
		} finally {
			blocked.release.countDown();
			other.release.countDown();
			Throwable cleanup = null;
			try {
				first.close();
			} catch (RuntimeException | Error failure) {
				cleanup = merge(cleanup, failure);
			}
			if (second != null) {
				try {
					second.close();
				} catch (RuntimeException | Error failure) {
					cleanup = merge(cleanup, failure);
				}
			}
			finishCleanup(primary, cleanup);
		}
		assertTrue(blocked.closeFinished.await(10, TimeUnit.SECONDS), "the first asynchronous cleanup finishes");
		assertTrue(other.closeFinished.await(10, TimeUnit.SECONDS), "the second asynchronous cleanup finishes");
		assertEquals(1, blocked.requests.get());
		assertEquals(1, other.requests.get());
		assertEquals(1, blocked.closes.get());
		assertEquals(1, other.closes.get());
	}

	@Test
	void registeringAnAlreadyExpiredDeadlineDoesNotRunCancellationInline() throws Exception {
		AtomicReference<Runnable> expiry = new AtomicReference<>();
		QueryExecutionDeadline deadline = QueryExecutionDeadline.start(60_000, (task, at) -> {
			expiry.set(task);
			return () -> {
			};
		});
		expiry.get().run();
		GatedSource source = new GatedSource(true);
		Timed limited = new Timed(source, deadline);
		ExecutorService caller = Executors.newSingleThreadExecutor();
		Future<?> registration = caller.submit(limited::registerDeadline);
		Throwable primary = null;
		try {
			assertTrue(source.entered.await(10, TimeUnit.SECONDS), "the expiration must reach cancellation");
			registration.get(3, TimeUnit.SECONDS);
			assertEquals(1, source.release.getCount(), "the callback is still blocked when registration returns");
		} catch (Exception | Error failure) {
			primary = failure;
			throw failure;
		} finally {
			source.release.countDown();
			Throwable cleanup = null;
			try {
				registration.get(10, TimeUnit.SECONDS);
			} catch (Exception | Error failure) {
				cleanup = merge(cleanup, failure);
			}
			try {
				limited.close();
			} catch (RuntimeException | Error failure) {
				cleanup = merge(cleanup, failure);
			}
			try {
				deadline.close();
			} catch (RuntimeException | Error failure) {
				cleanup = merge(cleanup, failure);
			}
			caller.shutdown();
			finishCleanup(primary, cleanup);
		}
		assertTrue(source.closeFinished.await(10, TimeUnit.SECONDS), "the admitted callback's cleanup finishes");
		assertEquals(1, source.requests.get());
		assertEquals(1, source.closes.get());
	}

	@Test
	void explicitCancellationReturnsActualDownstreamAcceptance() throws Exception {
		GatedSource source = new GatedSource(true);
		Timed limited = new Timed(source, 60_000);
		ExecutorService caller = Executors.newSingleThreadExecutor();
		Future<Boolean> request = caller.submit(limited::requestCancellation);
		try {
			assertTrue(source.entered.await(10, TimeUnit.SECONDS));
			assertFalse(request.isDone(), "explicit cancellation waits for downstream acceptance");
			source.release.countDown();
			assertTrue(request.get(10, TimeUnit.SECONDS));
		} finally {
			source.release.countDown();
			limited.close();
			caller.shutdown();
		}
		assertEquals(1, source.requests.get());
		assertEquals(1, source.closes.get());
		GatedSource declining = new GatedSource(false);
		declining.release.countDown();
		try (Timed other = new Timed(declining, 60_000)) {
			assertFalse(other.requestCancellation(), "a downstream refusal is not accepted merely by queueing work");
		}
		assertEquals(1, declining.requests.get());
		assertEquals(1, declining.closes.get());
	}

	@Test
	void timeoutInvokesSubclassCancellationOverrideForNonCooperativeDelegate() throws Exception {
		CountDownLatch called = new CountDownLatch(1);
		CountDownLatch sourceClosed = new CountDownLatch(1);
		AtomicInteger requests = new AtomicInteger();
		AtomicInteger closes = new AtomicInteger();
		CloseableIteration<String> source = new CloseableIteration<>() {
			@Override
			public boolean hasNext() {
				return false;
			}

			@Override
			public String next() {
				throw new NoSuchElementException();
			}

			@Override
			public void remove() {
				throw new UnsupportedOperationException();
			}

			@Override
			public void close() {
				closes.incrementAndGet();
				sourceClosed.countDown();
			}
		};
		try (TimeLimitIteration<String> limited = new TimeLimitIteration<>(source, 60_000) {
			@Override
			public boolean requestCancellation() {
				requests.incrementAndGet();
				called.countDown();
				return false;
			}

			@Override
			protected void throwInterruptedException() {
				throw new IllegalStateException("timed out");
			}
		}) {
			limited.interrupt();
			assertTrue(called.await(10, TimeUnit.SECONDS), "the subclass override must receive timeout cancellation");
			assertTrue(sourceClosed.await(10, TimeUnit.SECONDS),
					"a declining override must still allow source cleanup");
			assertEquals(1, requests.get());
			assertEquals(1, closes.get());
		}
		assertEquals(1, closes.get(), "subsequent explicit close must not close the source again");
	}

