	private static Throwable merge(Throwable primary, Throwable cleanup) {
		if (primary == null)
			return cleanup;
		if (cleanup != primary)
			primary.addSuppressed(cleanup);
		return primary;
	}

	private static void finishCleanup(Throwable primary, Throwable cleanup) throws Exception {
		if (cleanup == null)
			return;
		if (primary != null) {
			primary.addSuppressed(cleanup);
			return;
		}
		if (cleanup instanceof Exception exception)
			throw exception;
		throw (Error) cleanup;
	}

